(function(){
var RM=matchMedia('(prefers-reduced-motion: reduce)').matches;
function $(s,r){return (r||document).querySelector(s)}
function $$(s,r){return [].slice.call((r||document).querySelectorAll(s))}
function every(ms,fn){if(RM)return;setInterval(function(){if(!document.hidden)fn()},ms)}
function rnd(a,b){return Math.floor(a+Math.random()*(b-a+1))}
function pad(n){return (n<10?'0':'')+n}
function ic(el){if(window.ic)window.ic(el)}
function onView(sel,fn,th){var el=typeof sel==='string'?$(sel):sel;if(!el)return;if(!('IntersectionObserver' in window)){fn(el);return}
  var o=new IntersectionObserver(function(es){es.forEach(function(e){if(e.isIntersecting){o.disconnect();fn(el)}})},{threshold:th||.2});o.observe(el)}
function inView(el){if(!el)return false;var r=el.getBoundingClientRect();return r.bottom>0&&r.top<innerHeight}
function countTo(el,to,o){o=o||{};if(RM){return}var st=performance.now(),dur=o.dur||1400,dec=o.dec||0;
  (function f(n){var k=Math.min(1,(n-st)/dur),v=to*(1-Math.pow(1-k,3));el.textContent=o.fmt?o.fmt(v):(dec?v.toFixed(dec):Math.round(v).toLocaleString('en-US'));if(k<1)requestAnimationFrame(f)})(st)}

/* mobile nav */
var mb=$('#mbtn'),mn=$('#mnav');
if(mb&&mn){mb.addEventListener('click',function(){var open=mn.hidden;mn.hidden=!open;mb.setAttribute('aria-expanded',String(open))});
