  var acts=[].slice.call(document.querySelectorAll('#aiActs li')),toast=document.getElementById('aiToast'),timer=document.getElementById('aiT');
  var r0=document.getElementById('aiR0'),r1=document.getElementById('aiR1'),v0=document.getElementById('aiV0'),v1=document.getElementById('aiV1');
