  function esc(t){return String(t).replace(/[&<>]/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;'}[c]})}
  function visible(){if(!p.hasAttribute('data-on')||document.hidden)return false;var r=p.getBoundingClientRect();return r.bottom>0&&r.top<innerHeight}
  function wait(ms,g){return new Promise(function(res,rej){var t=0,last=Date.now();(function tick(){if(g!==gen)return rej('x');var n=Date.now();if(visible())t+=Math.min(200,n-last);last=n;if(t>=ms)return res();setTimeout(tick,60)})()})}
  function setSent(v){var from=sent;sent=v;var paint=function(x){x=Math.round(x);pct.textContent=x+'%';arc.style.strokeDasharray=x+' 100'};
    if(M&&!RM)M.animate(from,v,{duration:.9,ease:[.22,1,.36,1],onUpdate:paint});else paint(v);
