  function setRatio(c){r0.style.width=c+'%';r1.style.width=(100-c)+'%';v0.textContent=c+'%';v1.textContent=(100-c)+'%'}
  function enter(el){if(M&&!RM)M.animate(el,{opacity:[0,1],transform:['translateY(10px) scale(.97)','translateY(0px) scale(1)']},{type:'spring',stiffness:420,damping:32})}
  function bottom(){tl.scrollTop=tl.scrollHeight}
  function bubble(st){var d=document.createElement('div');d.className='ai-m'+(st.w==='ai'?' ai':'');var who=st.w==='ai'?'<i data-i="spark"></i>AI Assistant':'Meera Nair';
    d.innerHTML='<small>'+who+' · '+st.tm+'</small>'+esc(st.t);tl.appendChild(d);if(window.ic)window.ic(d);bottom();enter(d);return d}
  function tick(st){if(st.a===undefined)return;[].concat(st.a).forEach(function(i){var li=acts[i];li.classList.add('done');if(M&&!RM)M.animate(li,{transform:['translateX(-4px)','translateX(0px)']},{type:'spring',stiffness:500,damping:20})})}
