/* Motion (motion.dev): hero entrance, one-time scroll reveals, press feedback. Skipped entirely for reduced motion. */
(function(){
  var root=document.documentElement;
  function done(){root.classList.remove('m-pre')}
  var M=window.Motion;
  if(!M||matchMedia('(prefers-reduced-motion: reduce)').matches){done();return}
  var animate=M.animate,inView=M.inView,stagger=M.stagger,press=M.press;
  var EASE=[.22,1,.36,1];
  /* clear inline styles once finished so CSS hover transforms keep working */
  function clean(els){return function(){setTimeout(function(){els.forEach(function(el){el.style.opacity='';el.style.transform=''})},60)}}

  /* 1. hero entrance */
  var hero=[].slice.call(document.querySelectorAll('.hero-copy > *'));
  if(hero.length){
    hero.forEach(function(el){el.style.opacity='0'});
    animate(hero,{opacity:[0,1],transform:['translateY(22px)','translateY(0px)']},{duration:.8,ease:EASE,delay:stagger(.08,{startDelay:.05})}).then(clean(hero));
  }
  requestAnimationFrame(done);setTimeout(function(){hero.forEach(function(el){if(+getComputedStyle(el).opacity<1){el.style.opacity="";el.style.transform=""}})},4000);

  /* 2. scroll reveals: section headings, then card groups (staggered per container) */
  var seen=new WeakSet();
  function reveal(els,opts){
    els=els.filter(function(el){if(seen.has(el)||(el.parentElement&&el.parentElement.closest('.hero-copy,.mega,#inbox,.mnav')))return false;seen.add(el);return true});
    if(!els.length)return;
    var y=(opts&&opts.y)||24,sc=opts&&opts.scale;
    els.forEach(function(el){el.style.opacity='0';el.style.transform='translateY('+y+'px)'+(sc?' scale('+sc+')':'')});
    inView(els[0].parentElement||els[0],function(){
      animate(els,{opacity:[0,1],transform:['translateY('+y+'px)'+(sc?' scale('+sc+')':''),'translateY(0px)'+(sc?' scale(1)':'')]},{duration:.7,ease:EASE,delay:stagger(.07)}).then(clean(els));
    },{amount:.15});
  }
  /* headings: eyebrow + h2 + lead paragraph that open a section */
  [].forEach.call(document.querySelectorAll('section h2'),function(h){
    var grp=[h],p=h.previousElementSibling,n=h.nextElementSibling;
    if(p&&p.classList.contains('eyebrow'))grp.unshift(p);
    if(n&&n.tagName==='P')grp.push(n);
    reveal(grp,{y:18});
  });
  /* cards: group siblings by parent so each grid staggers on its own */
  var groups=new Map();
  [].forEach.call(document.querySelectorAll('section .feat, section .story, section .stat, section .cap, section .proof, section .glass.card, section .glass.dash, section .glass.form, section .glass.panel'),function(el){
    var k=el.parentElement;if(!groups.has(k))groups.set(k,[]);groups.get(k).push(el);
  });
  groups.forEach(function(els){reveal(els,{y:28})});
  /* hero product window + the cards under it */
  var win=document.getElementById('inbox');
  if(win)reveal([win],{y:36,scale:.98});
  reveal([].slice.call(document.querySelectorAll('.stage > .float')),{y:28});

  /* 3. press feedback on buttons (spring back on release) */
  press('.btn, .nl, .ov',function(el){
    animate(el,{scale:.96},{type:'spring',stiffness:600,damping:30});
    return function(){animate(el,{scale:1},{type:'spring',stiffness:500,damping:22}).then(function(){el.style.transform=''})};
  });
})();
